uniform highp sampler2D lookSettings;

attribute float lookId;
attribute vec3 lookInfo;
attribute vec3 s0;
attribute vec3 s1;
attribute vec4 s2;
attribute vec2 s3;
flat varying float vLookId;
varying vec3 vLookInfo;
varying vec2 vLookUv;
varying vec3 vLookWorld;
varying vec3 vLookWN;
varying vec3 vS0;
varying vec3 vS1;
varying vec4 vS2;
varying vec2 vS3;

vertexMain:
vLookId = lookId;
vLookInfo = lookInfo;
vLookUv = uv;
vLookWorld = (modelMatrix * vec4(position, 1.0)).xyz;
vLookWN = normalize(mat3(modelMatrix) * normal);
vS0 = s0;
vS1 = s1;
vS2 = s2;
vS3 = s3;

