void look_0(inout Look k) {
  p_size = texelFetch(lookSettings, ivec2(0, 0), 0).r;
  p_jitter = texelFetch(lookSettings, ivec2(1, 0), 0).r;
  p_stretch = texelFetch(lookSettings, ivec2(2, 0), 0).r;
  p_joint = texelFetch(lookSettings, ivec2(3, 0), 0).r;
  p_seed = texelFetch(lookSettings, ivec2(4, 0), 0).r;
  p_dome = texelFetch(lookSettings, ivec2(5, 0), 0).r;
  p_flat = texelFetch(lookSettings, ivec2(6, 0), 0).r;
  p_corner = texelFetch(lookSettings, ivec2(7, 0), 0).r;
  p_edgeRound = texelFetch(lookSettings, ivec2(8, 0), 0).r;
  p_edgeDrop = texelFetch(lookSettings, ivec2(9, 0), 0).r;
  p_chip = texelFetch(lookSettings, ivec2(10, 0), 0).r;
  p_sink = texelFetch(lookSettings, ivec2(11, 0), 0).r;
  p_tilt = texelFetch(lookSettings, ivec2(12, 0), 0).r;
  p_detail = texelFetch(lookSettings, ivec2(13, 0), 0).r;
  p_recess = texelFetch(lookSettings, ivec2(14, 0), 0).r;
  p_valueVar = texelFetch(lookSettings, ivec2(15, 0), 0).r;
  p_warm = texelFetch(lookSettings, ivec2(16, 0), 0).r;
  p_dark = texelFetch(lookSettings, ivec2(17, 0), 0).r;
  p_fleck = texelFetch(lookSettings, ivec2(18, 0), 0).r;
  p_polish = texelFetch(lookSettings, ivec2(19, 0), 0).r;
  p_dirt = texelFetch(lookSettings, ivec2(20, 0), 0).r;
  p_mossCover = texelFetch(lookSettings, ivec2(21, 0), 0).r;
  p_mossTop = texelFetch(lookSettings, ivec2(22, 0), 0).r;
  p_mossDepth = texelFetch(lookSettings, ivec2(23, 0), 0).r;
  p_mossScale = texelFetch(lookSettings, ivec2(24, 0), 0).r;
  p_wet = texelFetch(lookSettings, ivec2(25, 0), 0).r;
  p_grey = texelFetch(lookSettings, ivec2(26, 0), 0).rgb;
  p_brown = texelFetch(lookSettings, ivec2(27, 0), 0).rgb;
  p_sand = texelFetch(lookSettings, ivec2(28, 0), 0).rgb;
  p_mossDark = texelFetch(lookSettings, ivec2(29, 0), 0).rgb;
  p_mossLight = texelFetch(lookSettings, ivec2(30, 0), 0).rgb;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

  // the path's top: laid on the ground; any other face laid along its height
  bool top = vLookWN.y > 0.7;
  vec2 q;
  if (top) {
    q = vec2(vLookWorld.x, -vLookWorld.z);
  } else {
    vec3 n = normalize(vLookWN);
    vec3 along = normalize(vec3(-n.z, 0.0, n.x) + vec3(1e-5, 0.0, 0.0));
    q = vec2(dot(vLookWorld, along), vLookWorld.y);
  }
  vec2 fw = fwidth(q);
  float fp = max(max(fw.x, fw.y), 1e-6);
  cbFp = fp;
  CbS S = cbSample(q);

  // the cobble's colour: grey to brown by its own number, its lightness, a share of dark ones, flecks and mottling;
  // its worn top lighter and smoother, its edge dirtier
  vec4 R = S.rnd;
  float val = 1.0 + (R.x - 0.5) * 2.0 * p_valueVar;
  if (R.y < p_dark) val *= 0.55;
  vec3 stoneC = mix(p_grey, p_brown, clamp(R.w * p_warm * 2.0, 0.0, 1.0)) * val;
  float fl = cbN(q + R.xy * 91.0, 260.0);
  stoneC *= 1.0 + (smoothstep(0.6, 0.7, fl) * 0.6 - smoothstep(0.6, 0.7, 1.0 - fl) * 0.35) * p_fleck;
  stoneC *= 1.0 + (cbN(q + R.zw * 13.0, 12.0) - 0.5) * 0.45;
  float worn = (1.0 - smoothstep(0.0, 0.7, S.t)) * p_polish;
  stoneC *= 1.0 + 0.18 * worn;
  float edgeDirt = (1.0 - smoothstep(0.0, p_edgeRound * 1.6, S.d)) * p_dirt;
  stoneC *= 1.0 - 0.4 * edgeDirt;
  // the sand: its grains, darker in the joint's bottom
  vec3 sandC = p_sand * (0.7 + 0.6 * cbN(q, 300.0)) * (1.0 - 0.25 * p_dirt);
  float sm = S.stone * smoothstep(-fp, fp, S.d);
  vec3 col = mix(sandC, stoneC, sm);
  // the moss layer: dark to light green, lighter where its cushions stand up and catch the light, its thin fringe
  // letting the stone or sand under it show through
  float mossM = smoothstep(0.0, 0.6, S.moss);
  float lumpC = cbN(q + 5.1, 90.0);
  vec3 mossC = mix(p_mossDark, p_mossLight, clamp(cbN(q + 2.3, 2.0 / p_mossScale) * 1.4 - 0.2, 0.0, 1.0));
  mossC *= 0.7 + 0.6 * lumpC;
  col = mix(col, mossC, mossM);
  // the cavity: the sand darker toward the cobbles, a cobble's edge darker as it rounds down; the moss's own,
  // its cushions' hollows, over them
  float aoM = mix(0.45, 0.85, smoothstep(0.0, 0.6 * p_joint + 0.006, -S.d));
  float aoS = mix(0.6, 1.0, smoothstep(0.0, p_edgeRound * 1.4, S.d));
  float ao = mix(aoM, aoS, sm);
  k.ao = mix(ao, 0.7 + 0.3 * lumpC, mossM);
  k.aoDirect = 0.35;
  float rough = mix(0.97, mix(0.82, 0.5, worn), sm);
  rough = mix(rough, 1.0, mossM);
  // wet: the low places hold it first, darker and glossy; at full wet everything is
  float low = 1.0 - smoothstep(-p_recess - p_mossDepth - 0.004, -p_mossDepth - 0.004, S.h);
  float wetM = clamp(p_wet * 1.6 - (1.0 - low) * (1.0 - p_wet) * 1.6, 0.0, 1.0);
  col *= mix(1.0, 0.55, wetM);
  k.rough = mix(rough, 0.12, wetM);

  if (lookView > 0.5 && lookView < 1.5) col = mix(vec3(0.5), R.xyz, sm);
  if (lookView > 1.5 && lookView < 2.5) col = vec3((S.h + p_recess + p_mossDepth) / (p_recess + p_mossDepth));
  k.colour = col;
  // the relief as a height, bent into the normal by the pixel's neighbours; flat on a face that is not the top
  k.height = top ? S.h : 0.0;

}

void look_1(inout Look k) {
  p_stColour = texelFetch(lookSettings, ivec2(0, 1), 0).rgb;
  p_stMetal = texelFetch(lookSettings, ivec2(1, 1), 0).r;
  p_stRough = texelFetch(lookSettings, ivec2(2, 1), 0).r;
  p_stOil = texelFetch(lookSettings, ivec2(3, 1), 0).r;
  p_stOilColour = texelFetch(lookSettings, ivec2(4, 1), 0).rgb;
  p_stOilBrown = texelFetch(lookSettings, ivec2(5, 1), 0).rgb;
  p_stOilSize = texelFetch(lookSettings, ivec2(6, 1), 0).r;
  p_stOilRough = texelFetch(lookSettings, ivec2(7, 1), 0).r;
  p_stFinPitch = texelFetch(lookSettings, ivec2(8, 1), 0).r;
  p_stFinShare = texelFetch(lookSettings, ivec2(9, 1), 0).r;
  p_stFinDepth = texelFetch(lookSettings, ivec2(10, 1), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float brush = kn(vec2(uv.x * 4.0, uv.y * 900.0) + seed) * kfade(0.002);
    float wear = kfbm(uv * 3.0 + seed);
    vec3 stC = p_stColour * (0.9 + 0.12 * brush) * (0.9 + 0.15 * wear);
    float stM = p_stMetal;
    float stR = p_stRough + 0.15 * brush + 0.1 * wear;
    float stH = 0.00005 * brush;
    // fins: a rounded ridge of share stFinShare in each pitch along s3.x, the groove between them the depth down and
    // dark (the normal they bend is worked out below); fading to the fins' mean where a pitch is under a few pixels
    float stOn = step(0.5, s3.y);
    float stFade = kfade(p_stFinPitch * 4.0);
    float stF = fract(s3.x / p_stFinPitch);
    float stRidge = smoothstep(1.0 - 2.0 * p_stFinShare, 1.0, 0.5 + 0.5 * cos(6.28318 * stF));
    // far off, the fins' mean: the ridges' share lit, the rest groove
    float stShade = mix(p_stFinShare, stRidge, stFade);
    stC *= mix(1.0, 0.55 + 0.45 * stShade, stOn);
    // burnt castor oil: blotches and runs of a brown-black varnish; thick (glossy, brown in its highlight) or thin
    float stBlot = kfbm(uv * p_stOilSize + seed * 1.7);
    float stRun = kn(vec2(uv.x * p_stOilSize * 0.6, uv.y * p_stOilSize * 9.0) + seed + 11.0);
    float stThick = smoothstep(0.35, 0.75, 0.65 * stBlot + 0.35 * stRun);
    float stO = clamp(p_stOil * (0.75 + 0.35 * stThick), 0.0, 1.0);
    vec3 stOilC = mix(p_stOilColour, p_stOilBrown, stThick * (0.5 + 0.5 * kn(uv * 60.0 + seed)));
    stC = mix(stC, stOilC * mix(1.0, 0.6 + 0.4 * stShade, stOn), stO);
    stM = mix(stM, 0.12, stO);
    stR = mix(stR, mix(0.75, p_stOilRough, stThick), stO);
    stH += p_stOil * 0.00004 * stThick;
    k.colour = stC;
    k.metal = stM;
    k.rough = stR;
    k.height = stH;
    if (stOn > 0.5) {
      // the fins bend the normal from their profile's slope worked out exactly, not from the pixels' neighbours (whose
      // steps break thin rings into dots): the way s3.x grows across the surface, in the view's ways, from its change
      // between pixels (it is even across a face, so this is clean), times the profile's slope along it
      vec3 stN = normalize(vNormal);
      vec3 stPx = dFdx(-vViewPosition), stPy = dFdy(-vViewPosition);
      vec3 stR1 = cross(stPy, stN), stR2 = cross(stN, stPx);
      float stDet = dot(stPx, stR1);
      vec3 stG = (dFdx(s3.x) * stR1 + dFdy(s3.x) * stR2) / (abs(stDet) > 1e-14 ? stDet : 1e-14);
      float stPhi = 6.28318 * stF;
      float stA = 1.0 - 2.0 * p_stFinShare;
      float stT = clamp((0.5 + 0.5 * cos(stPhi) - stA) / (1.0 - stA), 0.0, 1.0);
      float stSlope = p_stFinDepth * 6.0 * stT * (1.0 - stT) / (1.0 - stA) * (-0.5 * sin(stPhi) * 6.28318 / p_stFinPitch);
      k.normal = normalize(stN - stFade * stSlope * stG);
      k.ownNormal = true;
    }

}

void look_2(inout Look k) {
  p_paSteel = texelFetch(lookSettings, ivec2(0, 2), 0).rgb;
  p_paSky = texelFetch(lookSettings, ivec2(1, 2), 0).rgb;
  p_paHorizon = texelFetch(lookSettings, ivec2(2, 2), 0).rgb;
  p_paFloor = texelFetch(lookSettings, ivec2(3, 2), 0).rgb;
  p_paPolish = texelFetch(lookSettings, ivec2(4, 2), 0).r;
  p_paBlur = texelFetch(lookSettings, ivec2(5, 2), 0).r;
  p_paBand = texelFetch(lookSettings, ivec2(6, 2), 0).r;
  p_paWindow = texelFetch(lookSettings, ivec2(7, 2), 0).r;
  p_paLit = texelFetch(lookSettings, ivec2(8, 2), 0).r;
  p_paGlint = texelFetch(lookSettings, ivec2(9, 2), 0).r;
  p_paMetal = texelFetch(lookSettings, ivec2(10, 2), 0).r;
  p_paRough = texelFetch(lookSettings, ivec2(11, 2), 0).r;
  p_paHammer = texelFetch(lookSettings, ivec2(12, 2), 0).r;
  p_paHammerSize = texelFetch(lookSettings, ivec2(13, 2), 0).r;
  p_paScratch = texelFetch(lookSettings, ivec2(14, 2), 0).r;
  p_paTarnish = texelFetch(lookSettings, ivec2(15, 2), 0).r;
  p_paTarnishColour = texelFetch(lookSettings, ivec2(16, 2), 0).rgb;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    vec3 paN = normalize(wn);
    vec3 paI = normalize(wp - cameraPosition);
    vec3 paR = reflect(paI, paN);
    float paUp = paR.y;
    float paB = p_paBlur;
    // the studio: the floor below, the sky above, a bright band at the horizon, a soft window high to one side
    vec3 paEnv = mix(p_paFloor, p_paSky, smoothstep(-paB, paB, paUp));
    paEnv = mix(paEnv, p_paHorizon, exp(-paUp * paUp / max(0.002, paB * paB * 0.25)) * p_paBand);
    paEnv += vec3(p_paWindow) * smoothstep(0.8, 0.97, dot(paR, normalize(vec3(0.35, 0.85, 0.4))));
    // the planishing hammer's facets: soft shallow dishes, gone to their mean where a pixel is as wide
    float paHf = kfade(1.0 / p_paHammerSize);
    float paH = (kn(uv * p_paHammerSize + seed) * 0.65 + kn(uv * p_paHammerSize * 2.3 + seed * 1.7) * 0.35) * paHf;
    // the polisher's scratches, fine and long
    float paS = kn(vec2(uv.x * 30.0, uv.y * 2400.0) + seed * 2.3) * kfade(0.0008);
    // tarnish in soft drifts, duller and browner
    float paT = p_paTarnish * smoothstep(0.45, 0.8, kfbm(uv * 5.0 + seed * 0.71));
    vec3 paBase = mix(p_paSteel, p_paSteel * p_paTarnishColour / 0.5, paT) * (1.0 - p_paScratch * paS);
    float paMix = p_paPolish * (1.0 - 0.6 * paT);
    vec3 paShown = clamp(paEnv * paBase / 0.65, 0.0, 1.0);
    // what the lights fall on is held down (paLit), or the sun on a plate already carrying its reflection burns it
    // white
    k.colour = mix(paBase * 0.85, paShown, paMix) * p_paLit;
    // a mirror in shade still shows the bright room: that share of the reflection is its own light
    k.glow = paShown * paMix * p_paGlint;
    k.metal = p_paMetal;
    k.rough = clamp(p_paRough + 0.25 * paT + 0.08 * paS, 0.02, 1.0);
    k.height = p_paHammer * paH;

}

