void look_8(inout Look k) {
  p_hbMetal = texelFetch(lookSettings, ivec2(0, 8), 0).rgb;
  p_hbTarnish = texelFetch(lookSettings, ivec2(1, 8), 0).rgb;
  p_hbTinColour = texelFetch(lookSettings, ivec2(2, 8), 0).rgb;
  p_hbFacet = texelFetch(lookSettings, ivec2(3, 8), 0).r;
  p_hbFacetRelief = texelFetch(lookSettings, ivec2(4, 8), 0).r;
  p_hbTarnishAmount = texelFetch(lookSettings, ivec2(5, 8), 0).r;
  p_hbTin = texelFetch(lookSettings, ivec2(6, 8), 0).r;
  p_hbTinWear = texelFetch(lookSettings, ivec2(7, 8), 0).r;
  p_hbRough = texelFetch(lookSettings, ivec2(8, 8), 0).r;
  p_hbRoughTarnish = texelFetch(lookSettings, ivec2(9, 8), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    // the facets: a jittered field of cells, each a shallow dish where one blow fell
    float hbId, hbE;
    float hbD = kvor(uv / p_hbFacet + seed * 3.0, hbId, hbE);
    float hbDish = mix(0.5, smoothstep(0.0, 0.7, hbD), kfade(p_hbFacet * 0.5));
    float hbShade = mix(0.5, hbId, kfade(p_hbFacet * 0.5));
    float hbFine = kfbm(uv * 30.0 + seed);
    // tarnish: patches by noise, more where the sheet curves in sharply (a crest's root, a brim's turn)
    float hbEdge = smoothstep(0.08, 0.5, hbCurve(normalize(wn)));
    float hbT = clamp(p_hbTarnishAmount * (smoothstep(0.45, 0.8, kfbm(uv * 4.0 + seed * 1.7)) * 1.4 + 0.5 * hbEdge), 0.0, 1.0);
    vec3 hbC = p_hbMetal * (0.85 + 0.25 * hbShade) * (0.92 + 0.12 * hbFine);
    // the tin over it, worn through on the high places and in patches
    float hbWear = smoothstep(1.0 - p_hbTinWear, 1.0 - p_hbTinWear + 0.15, kfbm(uv * 6.0 + seed + 9.0) * 0.7 + hbEdge * 0.5);
    float hbTinM = p_hbTin * (1.0 - hbWear);
    hbC = mix(hbC, p_hbTinColour * (0.9 + 0.15 * hbShade), hbTinM);
    k.colour = mix(hbC, p_hbTarnish * (0.8 + 0.4 * hbFine), hbT * (1.0 - 0.6 * hbTinM));
    k.metal = mix(0.95, 0.4, hbT);
    k.rough = mix(p_hbRough + 0.08 * hbShade, p_hbRoughTarnish, hbT);
    k.height = p_hbFacetRelief * (hbDish - 0.5) + 0.0001 * hbT;

}

